// ============================================================
// 题目注入逻辑
// ============================================================
function injectGuangdongQuestions() {
  if (typeof MAPS === 'undefined') {
    console.error('[广东题库] MAPS 未定义，无法注入题目');
    return;
  }

  const mapping = GUANGDONG_FRAMEWORK_MAP;
  let injectedCount = 0;

  for (const q of GUANGDONG_ALL_QUESTIONS) {
    const target = mapping[q.unitId];
    if (!target) continue;
    const map = MAPS[target.mapIndex];
    if (!map) continue;
    const unit = map.units[target.unitIndex];
    if (!unit) continue;
    if (!Array.isArray(unit.questions)) unit.questions = [];
    unit.questions.push(q);
    injectedCount++;
  }

  // 更新每单元的题目数量统计
  const stats = [];
  for (let m = 0; m < MAPS.length; m++) {
    for (let u = 0; u < MAPS[m].units.length; u++) {
      const qs = MAPS[m].units[u].questions || [];
      if (qs.length > 0) {
        stats.push(MAPS[m].name + ' 第' + (u+1) + '单元: ' + qs.length + '题');
      }
    }
  }
  console.log('[广东题库] 已注入', injectedCount, '道题目');
  console.log('[广东题库] 单元分布:', stats.join(' | '));
}

// 省份元数据
const PROVINCE_META = {
  code: 'guangdong',
  name: '广东',
  fullName: '广东省',
  examType: '普通高中学业水平选择性考试',
  textbookVersion: '统编版',
  policySource: GUANGDONG_OFFICIAL_POLICY_SOURCE,
  paperSources: GUANGDONG_PAPER_SOURCES,
  corpusAudit: GUANGDONG_CORPUS_AUDIT,
  totalQuestions: GUANGDONG_ALL_QUESTIONS.length
};

// 立即执行注入（本文件在 data/题库.js 之后加载，MAPS 已可用）
if (typeof MAPS !== 'undefined') {
  injectGuangdongQuestions();
}
